-- ============================================================================
-- Verification Queries:
--
-- 1. Verify Player Total Match Scores (should exactly equal 1240, 1080, 940, etc.):
-- SELECT 
--     mp.display_name,
--     COUNT(DISTINCT mp.match_id) AS matches_played,
--     SUM(mp.final_score) AS total_match_points,
--     SUM(mp.xp_earned) AS total_xp_earned
-- FROM public.match_participants mp
-- WHERE mp.match_id::text LIKE '22222222%'
--   AND mp.player_type = 'HUMAN'
-- GROUP BY mp.display_name
-- ORDER BY total_match_points DESC;
--
-- 2. Verify Hand Scores Sum matches mp.final_score:
-- SELECT 
--     mp.display_name,
--     COUNT(mhs.id) AS hands_played,
--     SUM(mhs.score_awarded) AS calculated_hand_score,
--     SUM(mp.final_score) AS recorded_final_score
-- FROM public.match_hand_scores mhs
-- JOIN public.match_participants mp ON mhs.participant_id = mp.id
-- WHERE mp.match_id::text LIKE '22222222%'
-- GROUP BY mp.display_name
-- ORDER BY recorded_final_score DESC;
-- ============================================================================
